after:
def lambda_handler(event, context):
  try:
    data = json.loads(event.get('body', '{}'))
    result = process(data)
    return {
      'statusCode': 200,
      'body': json.dumps(result)
    }
  except Exception as e:
    return {
      'statusCode': 500,
      'body': json.dumps({'error': str(e)})
    }

